-static int qce_skcipher_encrypt(struct skcipher_request *req)
-{
-	return qce_skcipher_crypt(req, 1);
-}
-
-static int qce_skcipher_decrypt(struct skcipher_request *req)
-{
-	return qce_skcipher_crypt(req, 0);
