@@ -699,7 +699,8 @@ static void st_nci_se_wt_timeout(struct timer_list *t)
 	struct st_nci_info *info = timer_container_of(info, t,
 						      se_info.bwi_timer);
 
-	info->se_info.bwi_active = false;
+	if (!xchg(&info->se_info.bwi_active, false))
+		return;
 
